double ln_one_plus_exp(double x)
{
double ln_one_plus_exp;
{
if ((x>37))
{
ln_one_plus_exp = x;
}
else
{
if ((x<(-37)))
{
ln_one_plus_exp = exp(x);
}
else
{
ln_one_plus_exp = log((1.0+exp(x)));
}
}
}
return(ln_one_plus_exp);
}
